  let jacobianYY = dot(uvDyTexels, uvDyTexels);
  let discriminant = sqrt(max(
    (jacobianXX - jacobianYY) * (jacobianXX - jacobianYY) +
      4.0 * jacobianXY * jacobianXY,
    0.0));
