  // the texels of each glyph's isolated group, so its pipeline takes
  // COMPOSITE_SHADER's straight color, expression for expression: an f16
  // target blends the straight color after converting it, so the entry and
  // its uncached glyph's group must round alike. Any other image keeps its
  // straight color unclamped: an extended-range canvas holds values past 1.
  let straightColor = select(
    premultipliedColor.rgb / sampledAlpha,
    clamp(premultipliedColor.rgb / max(sampledAlpha, 1e-6), vec3f(0.0), vec3f(1.0)),
    GROUP_STRAIGHT_COLOR);
