  // unpadded bbox center (same space $writeGradientExtension resolved
  // geom0..3 against), in the same local pixels as destPos/destSize.
  output.localOrigins = vec4f(destPos, gradRectPos + gradRectSize * 0.5);
  output.gradHalfSize = gradRectSize * 0.5;
